import React from 'react';
import { Brain, Calendar, Bell, Shield, Network, Zap, Database, Lock } from 'lucide-react';
import { useLanguage } from '../LanguageContext';
import './Architecture.css';

export default function Architecture() {
  const { t } = useLanguage();

  const cards = [
    {
      id: 'ai-engine',
      title: t('assistant'),
      icon: Brain,
      desc: t('aiEngineDesc'),
      color: '#FF7E5F',
      bg: '#FFF5F2'
    },
    {
      id: 'booking-core',
      title: 'Booking Core',
      icon: Calendar,
      desc: t('bookingCoreDesc'),
      color: '#4FACFE',
      bg: '#F0F9FF'
    },
    {
      id: 'notification-hub',
      title: 'Notification Hub',
      icon: Bell,
      desc: t('notificationHubDesc'),
      color: '#F093FB',
      bg: '#FDF2FF'
    },
    {
      id: 'security-layer',
      title: t('securityLayer'),
      icon: Shield,
      desc: t('securityLayerDesc'),
      color: '#43E97B',
      bg: '#F0FFF4'
    }
  ];

  return (
    <div className="architecture-page fade-in">
      <div className="arch-container">
        <header className="arch-header">
          <h1 className="arch-title">{t('archTitle')}</h1>
          <p className="arch-subtitle">{t('archSubtitle')}</p>
        </header>

        <div className="arch-grid">
          {cards.map((card, i) => (
            <div key={card.id} className={`arch-card fade-in-${i + 1}`}>
              <div className="card-inner">
                <div className="icon-wrapper" style={{ backgroundColor: card.bg, color: card.color }}>
                  <card.icon size={24} />
                </div>
                <h3 className="card-title">{card.title}</h3>
                <p className="card-desc">{card.desc}</p>
              </div>
            </div>
          ))}
        </div>

        <footer className="arch-footer fade-in-5">
          <p>{t('archFooter')}</p>
        </footer>

        <div className="tech-stack-section fade-in-6">
           <div className="tech-item"><Network size={16} /> Microservices</div>
           <div className="tech-item"><Zap size={16} /> Event-Driven</div>
           <div className="tech-item"><Database size={16} /> Distributed</div>
           <div className="tech-item"><Lock size={16} /> JWT Auth</div>
        </div>
      </div>
    </div>
  );
}
